example_solution:
# These variables are initialized on the command line (using '-v'):
# - n

BEGIN {
    if (n < 1) {
        print("invalid input")
        exit(1)
    }
    if (n == 1) {
        print(2)
        exit(0)
    }

    primes[1] = 2
    count = 1
    candidate = 1

    while (count < n) {
        while (1) {
            candidate += 2
            is_prime = 1
            i = 1
            while (primes[i] <= sqrt(candidate)) {
                if (candidate % primes[i] == 0) {
                    is_prime = 0
                    break
                }
                i++
            }
            if (is_prime) break
        }
        primes[++count] = candidate
    }

    print primes[n]
}

